static unsigned char *file(const char*p,size_t*n){FILE*f=fopen(p,"rb");assert(f);fseek(f,0,SEEK_END);long z=ftell(f);assert(z>0&&z<32*1024*1024);*n=(size_t)z;rewind(f);unsigned char*b=malloc(*n);assert(b&&fread(b,1,*n,f)==*n);fclose(f);return b;}
static TIOImageTestPolicy ownpolicy(unsigned char*b,size_t length){
 const struct mach_header_64*h=(const void*)b;TIOImageTestPolicy p={.cpu=(uint32_t)h->cputype,.relative_path="Frameworks/Public.dylib"};size_t o=sizeof*h;for(uint32_t i=0;i<h->ncmds;i++){const struct load_command*l=(const void*)(b+o);assert(l->cmdsize>=8&&o+l->cmdsize<=length);if(l->cmd==LC_UUID)memcpy(p.uuid,((const struct uuid_command*)l)->uuid,16);if(l->cmd==LC_SEGMENT_64){const struct segment_command_64*s=(const void*)l;const struct section_64*t=(const void*)(s+1);for(uint32_t j=0;j<s->nsects;j++)if(!strcmp(t[j].sectname,"__text")){p.text_va=t[j].addr;p.text_size=t[j].size;assert(t[j].offset+t[j].size<=length);CC_SHA256(b+t[j].offset,(CC_LONG)t[j].size,p.text_sha);}}o+=l->cmdsize;}return p;
}
