 CHECK(TIOImageOK,TIOMemoryCopySelf,p.relative_path,1,(intptr_t)b);assert(r.content_verified&&!r.loaded_identity_verified);b[4096]^=1;CHECK(TIOImageIdentityMismatch,TIOMemoryCopySelf,p.relative_path,1,(intptr_t)b);b[4096]^=1;u->uuid[0]^=1;CHECK(TIOImageIdentityMismatch,TIOMemoryCopySelf,p.relative_path,1,(intptr_t)b);u->uuid[0]^=1;CHECK(TIOImageDuplicate,TIOMemoryCopySelf,p.relative_path,2,(intptr_t)b);CHECK(TIOImagePathRejected,TIOMemoryCopySelf,"../Public",1,(intptr_t)b);CHECK(TIOImageCopyFailed,shortread,p.relative_path,1,(intptr_t)b);uint32_t old=s->cmdsize;s->cmdsize=7;CHECK(TIOImageMalformed,TIOMemoryCopySelf,p.relative_path,1,(intptr_t)b);s->cmdsize=old;CHECK(TIOImageMalformed,TIOMemoryCopySelf,p.relative_path,1,INTPTR_MIN);struct segment_command_64 *extra=(void*)(u+1);*extra=*s;extra->cmdsize=72;extra->nsects=0;h->ncmds=3;h->sizeofcmds+=72;CHECK(TIOImageMalformed,TIOMemoryCopySelf,p.relative_path,1,(intptr_t)b);h->ncmds=2;h->sizeofcmds-=72;struct uuid_command *extra_uuid=(void*)(u+1);*extra_uuid=*u;h->ncmds=3;h->sizeofcmds+=24;CHECK(TIOImageIdentityMismatch,TIOMemoryCopySelf,p.relative_path,1,(intptr_t)b);h->ncmds=2;h->sizeofcmds-=24;TIOImageBudgetInit(&q);q.bytes_remaining=8;assert(TIOImageTestView(&p,(uintptr_t)b,(intptr_t)b,p.relative_path,1,TIOMemoryCopySelf,NULL,&q,&r)!=TIOImageOK);free(b);
