int main(int argc,char**argv){assert(argc==5);mapped_negative_tests();size_t n;unsigned char*b=file(argv[1],&n);TIOImageTestPolicy p=ownpolicy(b,n);void*h=dlopen(argv[1],RTLD_NOW|RTLD_LOCAL);assert(h);void*sym=dlsym(h,"tio_public_fixture");Dl_info info;assert(sym&&dladdr(sym,&info));TIOImageBudget budget;TIOImageProof proof;TIOImageBudgetInit(&budget);TIOImageStatus status=TIOImageTestLoaded(&p,info.dli_fbase,argv[2],TIOMemoryCopySelf,NULL,&budget,&proof);if(status)fprintf(stderr,"own loaded status %u\n",status);assert(!status&&proof.loaded_identity_verified);TIOImageBudgetInit(&budget);assert(TIOImageAttestLoaded(TIOImageFlutter,info.dli_fbase,argv[2],TIOMemoryCopySelf,NULL,&budget,&proof)!=TIOImageOK);free(b);TIOImageBudgetInit(&budget);for(int i=3;i<5;i++){b=file(argv[i],&n);status=TIOImageAttestStatic(i==3?TIOImageFlutter:TIOImageIsar,b,n,&budget,&proof);if(status)fprintf(stderr,"public member status %u role %d\n",status,i);assert(!status&&proof.content_verified&&!proof.loaded_identity_verified&&!proof.slot_runtime_writable_verified);if(i==3)assert(proof.slot_metadata_verified);free(b);}puts("image attestation own mapped/dyld negatives and public static members PASS");return 0;}
